import{_ as r}from"./chunks/5f914a131a1e26802a8b.C-XNM0jI.js";import{_ as a,C as o,o as n,c as s,j as e,a as i,E as l,a6 as h}from"./chunks/framework.CnPv4DE1.js";const v=JSON.parse('{"title":"重塑人生的完整指南（在6到12个月内）","description":"","frontmatter":{"title":"重塑人生的完整指南（在6到12个月内）","originalTitle":"A Full Guide To Reinvent Your Life (In 6-12 Months)","date":"2023-07-15","originalUrl":"https://thedankoe.com/letters/a-full-guide-to-reinvent-your-life-in-6-12-months/","minutes":13,"sourceHash":"f53d55e020a9955083a5bfd424f0a126275dce2558bf89145878966909855510","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/a-full-guide-to-reinvent-your-life-in-6-12-months/"}]]},"headers":[],"relativePath":"letters/a-full-guide-to-reinvent-your-life-in-6-12-months.md","filePath":"letters/a-full-guide-to-reinvent-your-life-in-6-12-months.md"}'),m={name:"letters/a-full-guide-to-reinvent-your-life-in-6-12-months.md"};function d(u,p,f,c,g,_){const t=o("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"重塑人生的完整指南-在6到12个月内",tabindex:"-1"},[i("重塑人生的完整指南（在6到12个月内） "),e("a",{class:"header-anchor",href:"#重塑人生的完整指南-在6到12个月内","aria-label":'Permalink to "重塑人生的完整指南（在6到12个月内）"'},"​")],-1)),l(t),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/EdrNo3w_EWc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>人生就像一间暗室。</p><p>偶尔，我们会找到一根蜡烛，借此看清周围，但光亮维持不了多久。</p><p>蜡烛提供了视野和方向。</p><p>但火焰终会熄灭，在我们的灵魂中激起恐惧，生怕自己再也找不到出路……除非我们怀揣着能找到下一根蜡烛的信念继续前行。</p><p>人类的思维在清晰与混乱之间来回横跳。</p><p>混乱是我们的默认状态。</p><p>清晰是充斥我们意识的有序信息的副产品。当我们关注的事物清晰时，我们的头脑也就清晰了。</p><p>这是对人类行为的一种解释。</p><p>这也解释了为什么人们常说，他们生活中最痛苦的时光是周日上午10点到下午2点之间。</p><p>人们讨厌自己的工作，但相比于独自面对自己和漫无边际的思绪，工作能提供一种更愉悦的心境。</p><p>人类用各种活动填满一天，以此来构建他们的思维结构。</p><p>我们总是想做点什么。见见朋友、打打游戏、写作、设计、创作。最好是把注意力投资在有用的事情上。</p><p>当我们独处时，精神熵就会随之而来。</p><p>我们抓住一条连贯思路的时间往往不超过几分钟，然后就会迷失在未知之中。</p><p>我们的头脑会抓住消极的想法，然后任其繁衍滋生。</p><p>治愈这种心理状态的良药，就是懂得如何引导你的注意力。</p><p>冥想教你专注于呼吸。</p><p>元认知教你质疑自己的想法。</p><p>学会独处，就是学会在任何境遇下都能理顺思绪，以此获得愉悦。</p><p>讽刺的是，人们总是想要最大化自由。</p><p>这恰恰与他们真正想要的背道而驰。</p><p>人们想要的不是自由，而是自主权。</p><p>他们不希望被别人施加限制，他们想创造属于自己的限制。</p><p>你的“自我”就是一个定义。</p><p>是自我施加或被动接受的限制。</p><p>“自我”是你的精神躯体。你并不是纯粹物质形态的。</p><p>你是各种想法、信念和差异的混合体，这些基于你被设定的程序而被你视作重要之物。</p><p>你的自我决定了你如何解读境遇，进而决定了你如何行动。</p><p>你的自我决定了你的命运。</p><p>你可以随心所欲地定义自己，但大多数人都选择接受世界强加给他们的身份。</p><p>如果你的自我没有边界，那你就会死，因为这里的死亡是比喻意义上的。</p><p>它是意识内部差异性的毁灭。</p><p>如果自我与他者之间的界限被消除，那么构成你自我的形态也就消亡了。这就是自我消亡（Ego death）。你与宇宙融为一体。大多数人想要这个是因为它听起来很酷。对他们来说，这只不过是另一场身份地位的游戏罢了。</p><p>好了好了，抽象概念说得够多了，让我们来点实际的。</p><p>清晰是获得愉悦的关键。</p><p>但愉悦并不是拼图的全部。</p><p>我们可以享受别人分配给我们的生活，但这不会带来成就感。</p><p>可持续的、长期的清晰感来源于两个方面：</p><ol><li><p>与有意识的未来相一致的、自发生成的目标。</p></li><li><p>与无意识的未来相一致的、社会设定的目标。</p></li></ol><p>一个是你自己创造的，另一个是被分配的。</p><p>如果我们不想让自己的生活成为他人愿景的产物，我们就必须掌控自己的生活。</p><p>让我们深入探讨。</p><h2 id="大多数人不需要动力-他们需要清晰" tabindex="-1">大多数人不需要动力，他们需要清晰 <a class="header-anchor" href="#大多数人不需要动力-他们需要清晰" aria-label="Permalink to &quot;大多数人不需要动力，他们需要清晰&quot;">​</a></h2><p>动力就像站在峡谷的一侧。</p><p>另一侧看起来像个乌托邦。有你想要的一切。美丽的人、音乐、豪车、房子，都在呼唤你的名字让你纵身一跃，但你却没有办法跨越这条峡谷。</p><p>清晰，就是通向彼岸桥梁的第一块木板。</p><p>动力可以用多巴胺这种行为分子来解释。</p><p>当某物离我们“很远”时，我们会更渴望它。</p><p>当我们得到那件东西——比如房子、车子、佳人、手表，甚至是一门网络课程——我们会短暂地感觉良好。</p><p>但随后它就变得稀松平常了。</p><p>我们管这叫“蜜月期”。</p><p>话说回来，多巴胺并不是坏东西。<em>它是你生命中最重要的神经递质之一</em>。它是你梦想背后的驱动力。</p><p>问题在于我们不知道如何利用它。</p><p>大多数人都溺死在动力之中。</p><p>他们看到了太多遥不可及的东西，尤其是在社交媒体上。</p><p>他们一次又一次地浪费了为梦想采取行动的最宝贵的能量源。</p><p>即使他们确实得到了想要的东西，比如一辆车，他们也不知道如何转移注意力来维持对那件东西的愉悦感。</p><p>像血清素、催产素、内啡肽和内源性大麻素这类“此时此地”的神经递质，能让你对眼前的事物感到满足并懂得欣赏。</p><p>虽然有些人服用摇头丸（molly）和大麻等药物来让自己进入当下（我没在评判，我也吸过），但有更可持续的方法来做到这一点。</p><p><strong>1) 正念与细节</strong></p><p>关注你的感官能提供的细节。</p><p>当你散步时，试着去<em>看到</em>比以往更多的东西。</p><p>从你盲目的、“正常的”、浮于表面的日常生活中挣脱出来。</p><p>注意树叶上丰富的细节、草叶的纹理，以及汽车驶过时光线的闪耀。</p><p>做饭时，留意质地、味道和口感上的差异。试着去分辨各种食材。</p><p>听歌时，深挖进去。你能听到背景里微妙的层次吗？那是创作者有意为之的。他们希望你注意到这些。</p><p>你可以看出为什么美食评论家、音乐爱好者和瑜伽练习者如此享受某些活动。因为当下的这一刻本身就令人愉悦。</p><p>这就是现实。一种川流不息的体验质感。</p><p>当你得到的东西快要让你感到无聊时，应用这个策略。还有一个完整的世界等着你去发现。</p><p><strong>2) 培养一种内在哲学</strong></p><p>让我们想象一位年轻的健美运动员。</p><p>他们一开始去健身房是出于虚荣，但留下来是为了治愈自己。</p><p>他们渴望强壮、充满美感的体格，好吸引伴侣并赢得尊重。</p><p>但是，一两年后，他们的进步急剧放缓。</p><p>他们练就了一副好身材，但接下来呢？</p><p>这并没有改变他们吸引到的人数。也许这让他们在社会阶层中稍微上升了一点。但为了什么呢？为了多一点关注？还值得每周在这个事情上花费7到8个小时吗？</p><p>于是，他们向内看。</p><p>这给我的生活带来了什么？</p><p>为什么我还要每天坚持来？</p><p>否则我的时间会花在哪里？</p><p>这对我遇到的人、我能进行的对话以及对我敞开的职业机会产生了怎样的影响？</p><p>他们意识到，自己对物质的追求其实在本质上是极其非物质的。大多数追求都是如此，只是人们往往忽略了这个事实。</p><p>他们对“变得更好”的追求赋予了他们一种身份认同，这种认同影响了他们做出积极的决定。这防止了他们沦为盲目的大众。</p><p>教训是：</p><p>追求表面上的东西，也比在生活中无所事事要好。你要么了解了自己不想要什么，从而去追求你真正想要的；要么就在这沿途中找到了深度、意义和精神寄托。</p><p><strong>3) 学习与教育</strong></p><p>95%的人会对买了一辆全新保时捷GT3的人嗤之以鼻。</p><p>那是因为他们只看到了表面。</p><p>他们无法敞开心扉去想，那个人的身份认同远不止他们生活的这一个缩影。</p><p>如果买这车的人是个机械师呢？</p><p>如果他们从钻研机械中获得了深深的满足感呢？</p><p>现在，如果一个普通人买下了同样的东西，但决定去学点新知识呢？而不是无所事事地去获取更多物质？</p><p>他们可以通过教育，一路摸索进入现实的更深层面。</p><p>他们研究汽车的零部件、历史以及如何驾驶得更好。</p><p>他们开始去赛道，这辆车成了他们生活方式中固定的部分。一个能带来愉悦和心流的部分。</p><p>他们在物质的基石上建造了一座充满意义的房子。而大多数人则是不停地打地基，却从未建起任何值得保留的东西。</p><p><em>有了这种认知，美好生活的关键就在于：在有意义的多巴胺来源与达成目标时创造满足感之间，保持一种自律的平衡</em>_._</p><h2 id="愉悦-vs-快感-明智地选择你的多巴胺来源" tabindex="-1">愉悦 VS 快感（明智地选择你的多巴胺来源） <a class="header-anchor" href="#愉悦-vs-快感-明智地选择你的多巴胺来源" aria-label="Permalink to &quot;愉悦 VS 快感（明智地选择你的多巴胺来源）&quot;">​</a></h2><p>愉悦来自于投资注意力。</p><p>快感来自于消费注意力。</p><p>投资是长期的。</p><p>消费是短期的。</p><p>愉悦关注的是过程。</p><p>快感关注的是结果。</p><p>愉悦是朝着长期目标的不断推进。</p><p>快感是不费吹灰之力就达成目标。</p><p>我们的目标是最大化日常生活中的愉悦感。这也是所有人努力想做的。但他们没有足够抽离出来，建立一个能防干扰的全局视角。他们只关注此时此地能带来快感的东西。</p><p>我们不想陷入无休止地刷社交媒体、进行无意义的性行为（不只是身体上的），以及在评论区赢下除了浪费时间以外毫无意义的争论。</p><p>我们想要为目标采取行动，在现实中建立有益的东西，并以一种能给我们的生活带来愉悦的方式去影响他人。</p><h3 id="反向愿景" tabindex="-1">反向愿景 <a class="header-anchor" href="#反向愿景" aria-label="Permalink to &quot;反向愿景&quot;">​</a></h3><p>我曾<em>多次</em>谈到要拥有对未来的愿景。</p><p>为什么？</p><p>因为在我人生中取得实质性进展（并享受其中每一秒）的每一个时刻，我都拼命想要实现我脑海中的一个愿景。</p><p>经历过相同情况的人都懂得这种力量。</p><p>这就是为什么我写了这么多关于它的内容。</p><p>我想进一步理解它。</p><p>我想写到能整理出一套流程，从而帮助更多人创造并实现他们自己的愿景。</p><p>我创造的一个帮助过很多人的概念叫作<em>反向愿景</em>。</p><p>简而言之，这就是你如何认清自己不想要什么的过程。</p><p>那些你讨厌的、不想让其成为你生活一部分的事情。</p><p>这意味着你能立刻摆脱它们吗？</p><p>当然不是。</p><p>如果你已经围绕你的工作或家乡建立了一整套责任体系，你不可能说辞职就辞职，说搬走就搬走。如果你辞职，面临的风险远不止是钱的问题。在这件事上要放聪明点。这是场长期游戏。</p><p>要创建你的反向愿景：</p><p><strong>1) 把观察社会作为一种习惯</strong> – 在任何情况下都要密切关注周围的人。他们为什么要这么做？这会导致什么结果？他们是你想要成为的那种人吗？</p><p>可以很简单，比如观察他们购物篮里的商品，观察他们的身材，然后意识到你不想因为自己的购物习惯，最终变得迟钝、超重且懒惰。</p><p><strong>2) 反思你的过去</strong> – 有哪些经历是你再也不想经历第二次的？你生命中最低谷的时刻是什么？是什么造成的？你是否采取了什么措施来防止这种事再次发生？</p><p>把这变成你生活中有意识的练习。</p><p><strong>3) 列出你不想要的东西</strong> – 拿出一个笔记本，写得具体些。这份清单应该让你感到不适。</p><p>把它存放在安全的地方。当有新想法出现时，就补充进去。</p><p><strong>4) 认清如果你继续做同样的事，你会身处何方</strong> – 你就是你的习惯。如果你在10年后还保持同样的生活方式，你的人生最终会落得什么下场？</p><p>你想要那样吗？</p><p><strong>5) 将这种能量转化为充满激情的愿景</strong> – 每天你必须学习、建设和执行什么，才能避开你的反向愿景？</p><p>如果你想把你的愿景变成一个品牌，把你的笔记变成内容，从而建立一个真实的一人企业，<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">点击这里了解 2 Hour Writer。</a></p><h3 id="愿景" tabindex="-1">愿景 <a class="header-anchor" href="#愿景" aria-label="Permalink to &quot;愿景&quot;">​</a></h3><p>你的愿景就是你的框架。</p><p>它是你深藏脑海中，用来指导你日常行动的东西。</p><p>这不是关于拥有长期或短期焦点，而是两者都要有。</p><p><img src="'+r+'" alt=""></p><p>既然你已经为你的未来创建了一个具体的反向愿景（anti-vision），你的大脑就已经为模式识别做好了准备。</p><p>是的，具体明确你从生活中想要什么是有帮助的，但我会把这个任务交给你。</p><p>花点时间写下你反向愿景的对立面。具体描绘出你梦想中的生活是什么样的。</p><p>通过这样做，你让大脑能够捕捉到那些你通常会错过的机会。</p><p>你的愿景可能还不够“强大”，但你无法改进不存在的东西。</p><p>将你的愿景铭记于心，开始通过教育、实践和建设来执行一个更美好的未来。</p><h2 id="如何学习与建设" tabindex="-1">如何学习与建设 <a class="header-anchor" href="#如何学习与建设" aria-label="Permalink to &quot;如何学习与建设&quot;">​</a></h2><p>学校不能，也不会，教你如何建立你的梦想。</p><p>学校与政府、政治和经济密切相关。他们的规训过程（教育）是为了维持这些事物的运转而设立的。</p><p>任何赋予个人权力的东西都是一种威胁。</p><p>自我教育是你旅程中的一项必需品。</p><p>显而易见，以你当前的发展水平，你无法实现你的目标。</p><p>你必须学习实现它们所必需的技能。</p><p>否则它也就没有挑战性了，不是吗？</p><p>挑战在心流状态、享受和多巴胺中起着至关重要的作用——但前提是你接受的挑战不能太无聊，也不能太困难。在你的水平上玩，但要努力达到下一个水平。</p><p>如果你想保留你学到的所有东西（或者至少是重要的东西，而不是噪音），那么你必须边学边建。</p><p>以下是你要做的：</p><p><strong>1) 写下10-20个将实现你愿景的具体技能、兴趣或主题</strong></p><p>现在，我们需要清楚每天需要做些什么来实现我们的愿景。</p><p>大多数人未能取得实质性进展，是因为他们没有意识到，终身教育、技能获取和实践的习惯，才是你建立更好生活的方式。</p><p>这不是可选项。</p><p>如果你每天没有腾出时间来<em>终生练习你的手艺，</em>那你就到不了任何有意义的地方。</p><p>生活本身就是一场实践，而人们却没有站出来。</p><p>他们坐在家里，用无脑的娱乐来分散自己的注意力。</p><p>你没有理想的生活方式，是因为你现在并没有在更小的规模上过着那种生活方式。随着你在所做的事情上变得更好，你花在上面的时间就会增加，赚钱也就成了必然。</p><p>这一切的关键在于具体性。</p><p>不要写“网页设计”。</p><p>写下“如何创建对企业真正有用的落地页”。</p><p>不要写“去健身房”。</p><p>写下“在6周内减掉10磅脂肪的饮食和训练原则”。</p><p>至少做10次。</p><p>如果你看不出这些技能或兴趣将如何帮助你实现愿景，就删掉它们。</p><p><strong>2) 通过模式识别与动能利用多巴胺杠杆</strong></p><p>关联想法或注意现实中的模式，会提高大脑中的多巴胺水平。</p><p>这与可卡因感觉如此之好（多巴胺）的原因是一样的，但这种方式要可持续得多。它是会上瘾的。</p><p>随着动能的增加，这个过程会变得更强大。</p><p>把它想象成做数独游戏。</p><p>你想出一个答案——多巴胺增加。</p><p>然后，就像施了魔法一样，其他答案也一一归位，你无法停止解谜——多巴胺复利般增长。</p><p>当你在晚上产生一个想法，从而引发另外10个让你彻夜难眠的想法时，同样的事情也会发生。</p><p>当你注意到一个与你愿景相连的想法时，你的信噪比就会提高。</p><p>你的注意力会集中在<em>更多</em>相关信息上，你的大脑也会因兴奋而亮起。</p><p><em>这就是为什么“有目标地生活”感觉如此美妙。</em></p><p><strong>3) 学习与建设 –</strong> <strong>消除</strong> <strong>无用信息</strong></p><p>每个人都在告诉你该做什么。</p><p>他们把自己认为重要的东西投射到你身上。</p><p>如果你还没达到生活中理想的状态，没有什么比你的目标更重要。</p><p>不是新闻，不是你朋友的情感问题，更绝不是谁将当选。</p><p>关于选举的部分——为什么人们对汽油价格以及是否能生孩子这么愤愤不平？</p><p>因为投一张票比改变你的生活容易得多。</p><p>我不是说这些问题对你来说不重要，我是说“投票”是解决它们最糟糕的方式。</p><p>拉大视角。</p><p>建立一家企业，这样你就不必再操心汽油价格。</p><p>建立受众群体，向数百万人展示你的观点，这样你才能对身体权利的投票<em>真正</em>产生影响。</p><p>把你的愿景变成现实的唯一途径就是创造。</p><p>为了创造，你的创造力需要边界（否则事情会变得太混乱且令人窒息）。</p><p>你需要把目标转化为项目，这样你才有具体的、摸得着的东西可以去着手。这些为你的学习和创造力提供了边界。</p><p>现在就把你的愿景分解成目标。年度、月度、周度。</p><p>将它们全部转化为你可以着手的具体项目的里程碑，比如<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">个人品牌或一人企业</a>。一些整体的、并与你共同进化的东西。而不是一个听起来好得令人难以置信的静态商业模式。</p><p>牢记你的愿景和项目，开始建设和学习。</p><p>每天都在你的项目上工作，不管你知不知道自己在干嘛。</p><p>你不知道自己在干嘛，是因为你还没有遇到能为你构建学习框架的问题。</p><p>那才是最好的学习方式。</p><p>遇到一个<em>真实世界</em>的问题。</p><p>研究特定的信息来解决它。</p><p>保持信息从你的消费中稳定地流淌。</p><p>解决问题，享受多巴胺，让动能将你带入一个充满强度的时期。</p><p>剩下的就掌握在你手中了。</p><p>– Dan</p><hr><p><a href="/en/letters/a-full-guide-to-reinvent-your-life-in-6-12-months">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',211))])}const T=a(m,[["render",d]]);export{v as __pageData,T as default};
